INSERT INTO `ai_kb_chunk` VALUES (1,1,101,201,'GUIDE',50,'导学 · CS-01-A',1,'大学计算机基础（一）· 课程导学\n学分 2.0　周次 12 周（12 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 40% + 终结性考核（期末考试）× 60%\n一级项 二级项 权重 说明\n平时成绩\n40% 课堂测试 35 共 7 次、每次 5 分，随堂完成；缺考当次计 0 分\n三级项目 20 个人项目（Office 基础）：Excel 数据处理、函数、透视表等；提交以「学号 + 姓名」命名的 Excel 文件，题目不可重复\n课堂表现 5 出勤、提问与课堂参与\n课后作业 40 共 4 次、每次 10 分；逾期不补交\n终结性考核\n60% 期末考试 60 卷面 100 分，按 60% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格，与卷面分无关。',388,'2026-10-29 19:16:32'),(2,1,101,201,'GUIDE',50,'导学 · CS-01-A',2,'\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格，与卷面分无关。\n扣分（只影响平时分与预警结论）：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n课堂测试、课后作业缺考或缺交按 0 分计；请假请提前在学习平台提交。\n三、平时分怎么拿满\n课堂测试 7 次共 35 分，缺一次直接损失 5 分，尽量不缺席。\n三级项目占 20 分，建议第 3 周前定题；文件命名或格式不符会扣分。\n课后作业 4 次共 40 分，按次提交，逾期不补。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」，即按当前平时分测算的及格所需卷面分。',330,'2026-10-29 19:16:32'),(3,1,101,202,'GUIDE',51,'导学 · CS-02-A',1,'大学计算机基础（一）· 课程导学\n学分 2.0　周次 12 周（12 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 40% + 终结性考核（期末考试）× 60%\n一级项 二级项 权重 说明\n平时成绩\n40% 课堂测试 35 共 7 次、每次 5 分，随堂完成；缺考当次计 0 分\n三级项目 20 个人项目（Office 基础）：Excel 数据处理、函数、透视表等；提交以「学号 + 姓名」命名的 Excel 文件，题目不可重复\n课堂表现 5 出勤、提问与课堂参与\n课后作业 40 共 4 次、每次 10 分；逾期不补交\n终结性考核\n60% 期末考试 60 卷面 100 分，按 60% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格，与卷面分无关。',388,'2026-10-29 19:16:32'),(4,1,101,202,'GUIDE',51,'导学 · CS-02-A',2,'\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格，与卷面分无关。\n扣分（只影响平时分与预警结论）：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n课堂测试、课后作业缺考或缺交按 0 分计；请假请提前在学习平台提交。\n三、平时分怎么拿满\n课堂测试 7 次共 35 分，缺一次直接损失 5 分，尽量不缺席。\n三级项目占 20 分，建议第 3 周前定题；文件命名或格式不符会扣分。\n课后作业 4 次共 40 分，按次提交，逾期不补。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」，即按当前平时分测算的及格所需卷面分。',330,'2026-10-29 19:16:32'),(5,1,101,201,'RESOURCE',9,'第1讲_课程说明与考核方式.txt',1,'大学计算机基础（一）· 第1讲 课程说明\n1. 学分 2.0，12 周（12 次课）\n2. 总评 = 平时 40% + 期末考试 60%\n3. 平时 = 课堂测试 7×5 + 三级项目 20 + 课堂表现 5 + 课后作业 4×10\n4. 缺课超过 4 次按硬性不合格处理',136,'2026-10-29 19:16:32'),(6,1,101,201,'RESOURCE',10,'Excel三级项目_选题与提交要求.txt',1,'三级项目（个人）：Excel 数据处理、函数、透视表\n提交：以「学号+姓名」命名的 xlsx 文件\n选题不可与他人重复；第 10 周前提交',69,'2026-10-29 19:16:32'),(7,1,101,202,'RESOURCE',11,'期末复习提纲.txt',1,'期末复习提纲（赵明整理）\n考试范围：第 1~12 讲；题型：选择 40% + 简答 30% + 综合 30%',54,'2026-10-29 19:16:32'),(8,4,102,203,'GUIDE',52,'导学 · CS-01-B',1,'高等数学（一）· 课程导学\n学分 4.0　周次 16 周（16 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 40% + 终结性考核（期末考试）× 60%\n一级项 二级项 权重 说明\n平时成绩\n40% 课堂测试 30 共 6 次、每次 5 分，随堂小测；缺考当次计 0 分\n期中考试 20 第 8 周左右统一安排，卷面 100 分按 20 分折算\n课后作业 50 共 5 次、每次 10 分；逾期不补交\n终结性考核\n60% 期末考试 60 卷面 100 分，按 60% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（16 次课 → 允许缺 5 次）直接认定硬性不合格。\n扣分：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n期中考试缺考不安排补考，当次计 0 分；平时作业缺交同样计 0 分。\n三、平时分怎么拿满',406,'2026-10-29 19:18:35'),(9,4,102,203,'GUIDE',52,'导学 · CS-01-B',2,'超出 3 次后每次 −1 分。\n期中考试缺考不安排补考，当次计 0 分；平时作业缺交同样计 0 分。\n三、平时分怎么拿满\n课堂测试 6 次共 30 分，随堂进行，缺一次损失 5 分。\n课后作业 5 次共 50 分，是平时分的主体，建议当次课当天完成。\n期中考试占 20 分，范围覆盖前半学期内容，提前一周复习。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」，即按当前平时分测算的及格所需卷面分。',232,'2026-10-29 19:18:35'),(10,4,102,204,'GUIDE',53,'导学 · CS-02-B',1,'高等数学（一）· 课程导学\n学分 4.0　周次 16 周（16 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 40% + 终结性考核（期末考试）× 60%\n一级项 二级项 权重 说明\n平时成绩\n40% 课堂测试 30 共 6 次、每次 5 分，随堂小测；缺考当次计 0 分\n期中考试 20 第 8 周左右统一安排，卷面 100 分按 20 分折算\n课后作业 50 共 5 次、每次 10 分；逾期不补交\n终结性考核\n60% 期末考试 60 卷面 100 分，按 60% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（16 次课 → 允许缺 5 次）直接认定硬性不合格。\n扣分：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n期中考试缺考不安排补考，当次计 0 分；平时作业缺交同样计 0 分。\n三、平时分怎么拿满',406,'2026-10-29 19:18:35'),(11,4,102,204,'GUIDE',53,'导学 · CS-02-B',2,'超出 3 次后每次 −1 分。\n期中考试缺考不安排补考，当次计 0 分；平时作业缺交同样计 0 分。\n三、平时分怎么拿满\n课堂测试 6 次共 30 分，随堂进行，缺一次损失 5 分。\n课后作业 5 次共 50 分，是平时分的主体，建议当次课当天完成。\n期中考试占 20 分，范围覆盖前半学期内容，提前一周复习。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」，即按当前平时分测算的及格所需卷面分。',232,'2026-10-29 19:18:35'),(12,10,103,205,'GUIDE',54,'导学 · CS-01-C',1,'四史概述 · 课程导学\n学分 1.0　周次 12 周（12 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 60% + 终结性考核（期末考试）× 40%\n一级项 二级项 权重 说明\n平时成绩\n60% 课堂测试 35 共 7 次、每次 5 分，随堂完成；缺考当次计 0 分\n三级项目 20 团队项目（4–6 人）：参观或走访历史遗址 / 相关场馆，收集口述、影像与文献材料，完成选题与资料整理，并做阶段汇报\n四级项目 40 团队项目（同一小组）：在三级项目材料基础上完成 PPT 制作与课堂答辩，按内容、逻辑与表达打分\n课堂表现 5 出勤、发言与课堂参与\n终结性考核\n40% 期末考试 40 卷面 100 分，按 40% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格。',396,'2026-10-29 19:18:35'),(13,10,103,205,'GUIDE',54,'导学 · CS-01-C',2,' 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格。\n扣分：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n团队项目按小组统一评分，组内贡献差异由组长在贡献表中说明（合计 100%）。\n三、项目怎么做\n第 4 周前完成分组（4–6 人）并提交选题，避免与其它小组重复。\n三级项目重材料：参观/走访记录、照片、录音、文献摘录都要留档。\n四级项目重表达：PPT 控制在 10–12 页，答辩 8 分钟以内，组员分工陈述。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」。',313,'2026-10-29 19:18:35'),(14,10,103,206,'GUIDE',55,'导学 · CS-02-C',1,'四史概述 · 课程导学\n学分 1.0　周次 12 周（12 次课）　考核方式 考试课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 60% + 终结性考核（期末考试）× 40%\n一级项 二级项 权重 说明\n平时成绩\n60% 课堂测试 35 共 7 次、每次 5 分，随堂完成；缺考当次计 0 分\n三级项目 20 团队项目（4–6 人）：参观或走访历史遗址 / 相关场馆，收集口述、影像与文献材料，完成选题与资料整理，并做阶段汇报\n四级项目 40 团队项目（同一小组）：在三级项目材料基础上完成 PPT 制作与课堂答辩，按内容、逻辑与表达打分\n课堂表现 5 出勤、发言与课堂参与\n终结性考核\n40% 期末考试 40 卷面 100 分，按 40% 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格。',396,'2026-10-29 19:18:35'),(15,10,103,206,'GUIDE',55,'导学 · CS-02-C',2,' 折算计入总评\n二、考核与纪律\n及格线 60 分；缺课超过允许上限（12 次课 → 允许缺 4 次）直接认定硬性不合格。\n扣分：每次缺课 −2 分、迟到 −1 分、请假超出 3 次后每次 −1 分。\n团队项目按小组统一评分，组内贡献差异由组长在贡献表中说明（合计 100%）。\n三、项目怎么做\n第 4 周前完成分组（4–6 人）并提交选题，避免与其它小组重复。\n三级项目重材料：参观/走访记录、照片、录音、文献摘录都要留档。\n四级项目重表达：PPT 控制在 10–12 页，答辩 8 分钟以内，组员分工陈述。\n四、你会收到什么提示\n系统按考勤与成绩自动判定：缺课接近上限为黄色提醒、超过上限为红色；期末前会给出「期末需考分」。',313,'2026-10-29 19:18:35'),(16,7,104,207,'GUIDE',56,'导学 · CS-01-D',1,'数据结构（Java）· 课程导学\n学分 2.0　周次 16 周（16 次课）　考核方式 考查课　及格线 60 分\n一、成绩构成（总评 100 分）\n总评 = 平时成绩 × 40% + 终结性考核（大作业）× 60%\n一级项 二级项 权重 说明\n平时成绩\n40% 课堂测试 35 共 7 次、每次 5 分，随堂完成；缺考当次计 0 分\n三级项目 25 个人项目：课上用一节课完成，按教师给定的数据库表结构与任务要求，编写对应需求的代码结构\n课后作业 40 共 4 次、每次 10 分；逾期不补交\n终结性考核\n60% 大作业 60 团队项目（2–3 人）：从教师给定题目中选题自主开