--
-- Table structure for table `ai_report`
--

DROP TABLE IF EXISTS `ai_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_report` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `enrollment_id` bigint NOT NULL,
  `teaching_class_id` bigint NOT NULL,
  `offering_id` bigint NOT NULL,
  `course_id` bigint NOT NULL,
  `term_id` bigint NOT NULL,
  `report_type` varchar(20) NOT NULL DEFAULT 'STAGE' COMMENT 'STAGE / ALERT / MANUAL',
  `scope` varchar(20) NOT NULL DEFAULT 'STUDENT' COMMENT 'STUDENT / CLASS / ADMIN_CLASS',
  `period_start` date DEFAULT NULL,
  `period_end` date DEFAULT NULL,
  `risk_level` varchar(10) DEFAULT NULL COMMENT '生成时的预警等级快照',
  `total_score` decimal(6,2) DEFAULT NULL,
  `fact_json` json DEFAULT NULL COMMENT '生成所用事实（可复算）',
  `content_json` json DEFAULT NULL COMMENT '正文段落 + 动作按钮',
  `summary` varchar(300) DEFAULT NULL COMMENT '一句话结论',
  `status` varchar(20) NOT NULL DEFAULT 'PUBLISHED' COMMENT 'DRAFT / PUBLISHED',
  `source` varchar(20) NOT NULL DEFAULT 'TEMPLATE' COMMENT 'DIFY / TEMPLATE',
  `model` varchar(50) DEFAULT NULL,
  `app_id` varchar(64) DEFAULT NULL,
  `prompt_version` varchar(20) DEFAULT NULL,
  `run_id` bigint DEFAULT NULL,
  `tokens` int DEFAULT NULL,
  `cost` decimal(10,6) DEFAULT NULL,
  `read_time` datetime DEFAULT NULL,
  `publish_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `metrics_json` json DEFAULT NULL COMMENT '鍏?淮鎸囨爣蹇?収锛氬?鐢熷?/鐝?骇鍧囧?',
  `report_version` int NOT NULL DEFAULT '1' COMMENT '鎶ュ憡鐗堟湰锛屾瘡娆￠噸鏂扮敓鎴愰?澧',
  `stale` tinyint(1) NOT NULL DEFAULT '0' COMMENT '婧愭暟鎹?彉鏇村悗鏍囪?杩囨湡',
  `stale_reason` varchar(300) DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL COMMENT '浜嬪疄/鎸囨爣蹇?収鏃堕棿',
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`,`create_time`),
  KEY `idx_enrollment` (`enrollment_id`,`report_type`,`create_time`),
  KEY `idx_class` (`teaching_class_id`,`scope`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 学习评价报告';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ai_report`
--

LOCK TABLES `ai_report` WRITE;
