INSERT INTO `submission_answer` VALUES (910000,900001,90001,'{\"text\": \"（要点不足作答）sin(3x)~3x，故极限为 3，部分步骤缺失。\"}',6.00,NULL,'P2-9 验证后恢复 [人工改分 7→6]','TEACHER',1,'2026-11-09 19:58:59','2026-10-15 20:00:00','2026-11-09 19:58:59'),(910001,900001,90002,'{\"text\": \"（基本完整作答）f\'(x)>0 则严格递增；f\'(x)<0 则递减。\"}',7.00,NULL,'基本正确','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910002,900001,90003,'{\"text\": \"（基本完整作答）原函数 x²+x，结果 2；∫ₐᵇ f=F(b)−F(a)。\"}',8.00,NULL,'基本正确','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910003,900001,90004,'{\"text\": \"（完整作答）p=2>1 的 p 级数收敛，并补充了推导与例子。\"}',9.00,NULL,'要点齐全','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910004,900001,90005,'{\"text\": \"（完整作答）行列式非零；秩等于阶数，并补充了推导与例子。\"}',10.00,NULL,'要点齐全','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910010,900002,90001,'{\"text\": \"（完整作答）sin(3x)~3x，故极限为 3，并补充了推导与例子。\"}',10.00,NULL,'要点齐全','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910011,900002,90002,'{\"text\": \"（要点不足作答）f\'(x)>0 则严格递增；f\'(x)<0 则递减，部分步骤缺失。\"}',5.00,NULL,'要点不足','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910012,900002,90003,'{\"text\": \"（要点不足作答）原函数 x²+x，结果 2；∫ₐᵇ f=F(b)−F(a)，部分步骤缺失。\"}',6.00,NULL,'要点不足','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910013,900002,90004,'{\"text\": \"（基本完整作答）p=2>1 的 p 级数收敛。\"}',7.00,NULL,'基本正确','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910014,900002,90005,'{\"text\": \"（基本完整作答）行列式非零；秩等于阶数。\"}',8.00,NULL,'基本正确','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910020,900003,90001,'{\"text\": \"（要点不足作答）sin(3x)~3x，故极限为 3，部分步骤缺失。\"}',5.00,NULL,'要点不足','TEACHER',2,'2026-10-16 10:00:00','2026-10-15 20:00:00','2026-10-16 10:00:00'),(910021,900003,90002,'{\"text\": \"（要点不足作答）f\'(x)>0 则严格递增；f\'(x)<0 则递减，部分步骤缺失。\"}'